  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']

    # Build edges with mutual reachability
    edges = []
    for u, v, d in distances:
        if u not in core_dist or v not in core_dist:
            raise ValueError('Unknown node')
        w = max(core_dist[u], core_dist[v], d)
        if u < v:
            edge = (w, u, v)
        else:
            edge = (w, v, u)
        edges.append(edge)

    # Sort by weight, then lexicographically by node names
    edges.sort(key=lambda e: (e[0], e[1], e[2]))

    # Union-Find (deterministic, no recursion)
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True

    mst_edges = []
    total_weight = 0.0
    n = len(nodes)
    target = n - 1
    for w, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, w])
            total_weight += w
            if len(mst_edges) == target:
                break

    if len(mst_edges) != target:
        raise ValueError('Graph is disconnected')

    return {
        'mst_edges': mst_edges,
        'total_weight': total_weight
    }"
}
